 public static List<RpgItemSet> Sets()
 {
  var result=new List<RpgItemSet>();
  void S(string id,string name,params RpgSetBonus[] bonuses)=>result.Add(new(){Id=id,Name=name,ItemIds=Items().Where(i=>i.SetId==id).Select(i=>i.ItemId).ToList(),Bonuses=bonuses.ToList()});
  RpgSetBonus B(int n,string description,RpgAttributes? a=null)=>new(){RequiredPieces=n,Description=description,Attributes=a??new()};
  S("eternal_cosmic_forge","Sternenschmied des Urkosmos",
   B(1,"Sternenerwachen: +35 % Angriff",new(){AttackPercent=35}),
   B(2,"Kosmische Präzision: +25 % Krit-Chance, +50 % Krit-Schaden",new(){CritChance=25,CritDamage=50}),
   B(3,"Sternenfunken: Krits verursachen 180 % zusätzlichen Angriffsschaden; 5 s Abklingzeit"),
   B(4,"Himmlische Jagd: +50 % Boss-Schaden, +20 % Angriffstempo",new(){BossDamage=50,AttackSpeed=20}),
   B(5,"Galaktische Resonanz: direkte Treffer gewähren +4 % Gesamtschaden; bis 10 Stapel für 8 s"),
   B(6,"Zwillingssterne: +35 % Doppelangriff; Doppelangriffe verursachen einen zusätzlichen Treffer mit 150 % Angriffsschaden",new(){DoubleAttackChance=35}),
