  S("eternal_soul_devourer","Ewiger Seelenverschlinger",
   B(1,"Seelenhunger: +20 Prozentpunkte Lebensraub aus tatsächlich verursachtem direktem Schaden"),
   B(2,"Unstillbarer Durst: +30 % Angriff, +30 % Heilungswirkung",new(){AttackPercent=30,HealingPower=30}),
   B(3,"Seelenaufnahme: jeder fünfte direkte Treffer heilt 15 % maximale HP"),
   B(4,"Seelenrausch: tatsächliche Eigenheilung gewährt 8 s +30 % Gesamtschaden"),
   B(5,"Ernte der Verlorenen: direkte Krits gewähren +6 % Gesamtschaden; bis 8 Stapel für 10 s"),
   B(6,"Blut der Unsterblichen: einmal pro Bosskampf unter 30 % HP um 50 % maximale HP heilen"),
