   B(3,"Unerschöpfliche Schätze: +65 % Perlenfund; 40 % zusätzliche normale Tauchbeute",new(){PearlBonus=65}),
   B(4,"Jäger der Meere: +50 % Angriff, +40 % Boss-Schaden",new(){AttackPercent=50,BossDamage=40}),
